INSERT INTO npc_text (ID, text0_0, text0_1, prob0) VALUES (990100, 'Ce donjon peut être affronté dans une version bien plus redoutable.$B$BChoisissez le mode avant d\'engager le combat : une fois le premier ennemi abattu, il est verrouillé jusqu\'à la réinitialisation du donjon.$B$BMode niveau 40 : ennemis niveau 40, boss niveau 41.$BMode niveau 50 : ennemis niveau 50, boss niveau 51.', 'Ce donjon peut être affronté dans une version bien plus redoutable.$B$BChoisissez le mode avant d\'engager le combat : une fois le premier ennemi abattu, il est verrouillé jusqu\'à la réinitialisation du donjon.$B$BMode niveau 40 : ennemis niveau 40, boss niveau 41.$BMode niveau 50 : ennemis niveau 50, boss niveau 51.', 1);
