INSERT INTO quest_template (entry, Method, ZoneOrSort, MinLevel, QuestLevel, Type, SuggestedPlayers, QuestFlags, Title, Details, Objectives, OfferRewardText, RequestItemsText, EndText, ObjectiveText1, ReqCreatureOrGOId1, ReqCreatureOrGOCount1, RewChoiceItemId1, RewChoiceItemId2, RewChoiceItemId3, RewChoiceItemId4, RewChoiceItemId5, RewChoiceItemId6, RewChoiceItemCount1, RewChoiceItemCount2, RewChoiceItemCount3, RewChoiceItemCount4, RewChoiceItemCount5, RewChoiceItemCount6, RewOrReqMoney, RewMoneyMaxLevel) VALUES (990300, 2, 2437, 38, 41, 81, 5, 8, 'Gouffre de Ragefeu : l\'épreuve du niveau 40', 'Ce lieu peut révéler une puissance bien plus grande. Parlez-moi pour activer le mode niveau 40, puis abattez Taragaman l\'Affameur. Seuls les plus aguerris en reviendront.$B$BRapportez-moi la preuve de votre victoire et vous choisirez une pièce d\'équipement épique adaptée à votre armure.', 'Vaincre Taragaman l\'Affameur en mode niveau 40.', 'Vous l\'avez fait. Votre réputation va vous précéder, $N. Choisissez votre récompense.', 'Le mode niveau 40 vous attend, $N.', '', 'Taragaman l\'Affameur vaincu (mode 40)', 990200, 1, 991050, 991051, 991052, 991053, 991054, 991055, 1, 1, 1, 1, 1, 1, 15000, 3600);
